// Build the synthesis prompt + flat source list.
const row = $input.first().json;
if (!row || !row.raw_data) {
  const body = $('Webhook generate-review').first().json.body || {};
  return [{ json: { ok: false, __http_status: body.employee_id ? 404 : 400, error: body.employee_id ? 'employee_not_found' : 'employee_id_required', employee_id: body.employee_id || null } }];
}
const __ok = true;
const d = typeof row.raw_data === 'string' ? JSON.parse(row.raw_data) : row.raw_data;

// Flatten every input into a numbered source list with stable IDs.
const sources = [];
sources.push({ source_id: 'self_1', type: 'self_assessment', date: null, text: d.self_assessment });
for (const m of d.manager_feedback || []) sources.push({ source_id: m.id, type: 'manager_feedback', reviewer: m.reviewer, date: m.date, text: m.text });
for (const p of d.peer_feedback || []) sources.push({ source_id: p.id, type: 'peer_feedback', reviewer: p.reviewer, date: p.date, text: p.text });
for (const g of d.goals || []) sources.push({ source_id: g.id, type: 'goal', date: null, text: `Goal: ${g.goal} | Status: ${g.status} | Evidence: ${g.evidence}` });
for (const pr of d.project_outcomes || []) sources.push({ source_id: pr.id, type: 'project_outcome', date: null, text: `Project: ${pr.project} | Outcome: ${pr.outcome}` });
(d.meeting_notes || []).forEach((n, i) => sources.push({ source_id: `note_${i + 1}`, type: 'meeting_note', date: null, text: n }));

const validIds = sources.map(s => s.source_id);

const prompt = `You are an HR performance review synthesizer. Given the numbered source list below for ${d.name} (${d.role}), produce a structured performance review.

Rules:
- Every point MUST cite one or more source_id values from the list. Only these IDs are valid: ${validIds.join(', ')}
- Do NOT invent facts absent from the sources.
- Each point must be specific and evidence-based, quoting concrete outcomes, dates, or numbers where the sources contain them.
- 2-4 points per section.
- CRITICAL: Represent each source's claim FAITHFULLY. Do not soften, sanitize, or reword a reviewer's assertion into diplomatic language. If a manager says 'consistently misses deadlines', the growth area must state that claim as made - do NOT rewrite it as 'an opportunity to improve deadline adherence'. Your job is faithful synthesis, not diplomacy. A separate bias auditor downstream must be able to see the original strength of each claim in order to fairness-check it; softening claims defeats that audit and harms the employee.
- Do not add mitigating context to a negative claim unless a source explicitly provides it (cite that source if so).

SOURCES:
${JSON.stringify(sources, null, 2)}`;

return [{ json: { ok: true, employee_id: d.employee_id, name: d.name, role: d.role, prompt, sources, validIds } }];

