// Parse + validate synthesis output. Strip any hallucinated source_ids.
const ctx = $('Build synthesis prompt').first().json;
const resp = $input.first().json;
const raw = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Empty Gemini response: ' + JSON.stringify(resp).slice(0, 500));

let report;
try {
  report = JSON.parse(raw);
} catch (e) {
  throw new Error('Synthesis output was not valid JSON: ' + raw.slice(0, 500));
}

const valid = new Set(ctx.validIds);
const stripped = [];
for (const section of ['strengths', 'growth_areas', 'impact_highlights', 'goal_progress']) {
  report[section] = (report[section] || []).filter(pt => {
    pt.source_ids = (pt.source_ids || []).filter(id => valid.has(id));
    if (pt.source_ids.length === 0) { stripped.push({ section, text: pt.text }); return false; }
    pt.flag = null;
    return true;
  });
}

return [{ json: { employee_id: ctx.employee_id, name: ctx.name, role: ctx.role, report, sources: ctx.sources, stripped_uncited_points: stripped } }];

// Build the bias-audit prompt: report + sources + date distribution.
const j = $input.first().json;
const dates = j.sources.filter(s => s.date).map(s => `${s.source_id}: ${s.date}`);

// Give every point a stable ref like strengths[0] so flags can be merged back.
const points = [];
for (const section of ['strengths', 'growth_areas', 'impact_highlights', 'goal_progress']) {
  j.report[section].forEach((pt, i) => points.push({ point_ref: `${section}[${i}]`, text: pt.text, source_ids: pt.source_ids }));
}

const prompt = `You are a bias auditor for performance reviews. Audit EVERY point below against the source data.

For each point, check for exactly these issues:
1. unsupported_claim - the point (or the source it cites) asserts something with no concrete evidence anywhere in the sources
2. recency_bias - the point relies only on the most recent period while earlier sources show relevant contrary or additional evidence (see date distribution)
3. single_source_bias - a SUBJECTIVE character judgement resting on one reviewer with NO concrete verifiable example. If the single source gives a specific incident, PR number, date, or measurable outcome, do NOT flag it.
4. vague_language - the point or its cited source uses generic, non-specific language with no examples, numbers, named projects, or measurable outcomes. This applies to POSITIVE praise too: 'great team player', 'helpful and flexible', 'be more proactive' are all vague_language (severity low or medium) when nothing in the cited sources gives an observable action or outcome. Generic goodwill is not evidence.
5. contradiction - the point's substantive claim about performance conflicts with goals or project_outcomes evidence (e.g. 'misses deadlines' when outcomes show on-time delivery). A minor date/detail discrepancy between two sources describing the SAME event is NOT a contradiction - ignore it.

Rules:
- Output one entry per point, in the same order, using its point_ref.
- DEFAULT TO flag: null. Most points in a fair review are fine. Only flag when a specific, nameable problem exists. A point citing 3+ sources or citing objective goal/project evidence is almost never biased.
- Do not flag a point for citing few sources when those sources are objective records (goals, project_outcomes). Positive points are not exempt from vague_language: praise with no concrete example anywhere in its cited sources must be flagged vague_language.
- severity: low | medium | high. Use high when: a claim is contradicted by objective goal/project evidence, OR a negative judgement about the person has no supporting example anywhere in the sources. Use low only for wording/tone issues. Do not under-call severity on unevidenced criticism - that is the most harmful bias in a review.
- When a negative claim about the employee is contradicted by objective evidence, prefer type 'contradiction' over 'unsupported_claim'.
- reasoning must name the specific sources that support or undermine the point.
- Also output overall_bias_summary: 2-3 sentences on the overall fairness of this review and any reviewer imbalance (e.g. count of manager vs peer sources).

DATE DISTRIBUTION OF SOURCES:
${dates.join('\n')}

REPORT POINTS:
${JSON.stringify(points, null, 2)}

SOURCE DATA:
${JSON.stringify(j.sources, null, 2)}`;

return [{ json: { ...j, bias_prompt: prompt } }];

