// Validate audit completeness, then merge flags back by point_ref.
const ctx = $('Build bias prompt').first().json;
const resp = $input.first().json;
const raw = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!raw) throw new Error('Empty bias-agent response: ' + JSON.stringify(resp).slice(0, 500));
const audit = JSON.parse(raw);

const sections = ['strengths', 'growth_areas', 'impact_highlights', 'goal_progress'];
const expected = new Set();
for (const section of sections) {
  ctx.report[section].forEach((_, i) => expected.add(`${section}[${i}]`));
}

if (!Array.isArray(audit.audits)) throw new Error('Bias audit did not return an audits array');
const seen = new Set();
for (const a of audit.audits) {
  const ref = a?.point_ref;
  if (!expected.has(ref)) throw new Error('Bias audit returned unknown point_ref: ' + String(ref));
  if (seen.has(ref)) throw new Error('Bias audit returned duplicate point_ref: ' + ref);
  if (!(a.flag === null || (a.flag && ['unsupported_claim','recency_bias','single_source_bias','vague_language','contradiction'].includes(a.flag.type) && ['low','medium','high'].includes(a.flag.severity) && typeof a.flag.reasoning === 'string' && a.flag.reasoning.trim()))) {
    throw new Error('Bias audit returned malformed flag for ' + ref);
  }
  seen.add(ref);
}
const missing = [...expected].filter(ref => !seen.has(ref));
if (missing.length) throw new Error('Bias audit incomplete; missing: ' + missing.join(', '));

const report = ctx.report;
for (const a of audit.audits) {
  const match = /^(\w+)\[(\d+)\]$/.exec(a.point_ref);
  if (!match) throw new Error('Bias audit returned malformed point_ref: ' + a.point_ref);
  const [, section, index] = match;
  report[section][+index].flag = a.flag;
}

const flagCount = sections.flatMap(section => report[section]).filter(point => point.flag).length;
const strippedCount = Array.isArray(ctx.stripped_uncited_points) ? ctx.stripped_uncited_points.length : 0;
const final = {
  employee_id: ctx.employee_id,
  name: ctx.name,
  role: ctx.role,
  ...report,
  overall_bias_summary: audit.overall_bias_summary || '',
  flag_count: flagCount,
  audit_status: 'complete',
  audited_claims: seen.size,
  stripped_uncited_count: strippedCount,
  status: 'pending_approval'
};

return [{ json: { employee_id: ctx.employee_id, draft: final } }];
